import Fastify from "fastify";

type Product = { id: string; name: string; price: number };
const products: Product[] = [{ id: "notebook", name: "Notebook", price: 4.5 }];

export const app = Fastify();

// TODO: register GET /products/:id with typed params and a response schema
app.get("/products", async function list() {
    return products;
});
